observed_target_gate:
let target = exact_object(&op["target"], &["object_type", "ref"], &[])?;
string(target, "ref", false)?;
if !matches!(
    string(target, "object_type", false)?,
    "Material"
        | "Section"
        | "Node"
        | "Element"
        | "Component"
        | "Support"
        | "Load"
        | "Combination"
) {
    return Err("Unsupported target object_type".into());
}
